<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {ArrowUpRight,Search,RefreshCw,X,ShieldCheck} from 'lucide-vue-next'
import {api,type CapabilitySkill} from '../api'
import {useAppStore} from '../store'
import {availabilityLabel,networkLabel,roleLabel} from '../capability-ui'
const store=useAppStore(),route=useRoute(),router=useRouter(),tab=ref(route.query.tab==='tools'?'tools':'skills'),query=ref(String(route.query.q||'')),filter=ref('all'),dialog=ref<HTMLDialogElement>(),detail=ref<Awaited<ReturnType<typeof api.capabilitySkill>>|null>(null),detailError=ref(''),detailLoading=ref(false)
let detailAttempt=0
const rows=computed(()=>{const source=tab.value==='skills'?store.capabilityDirectory?.skills:store.capabilityDirectory?.tools;const q=query.value.trim().toLowerCase();return (source||[]).filter(item=>(!q||`${item.name} ${item.description} ${'group' in item?item.group:''}`.toLowerCase().includes(q))&&(filter.value==='all'||item.available===(filter.value==='available')))})
async function refresh(){await store.loadCapabilityDirectory().catch(()=>{})}
async function activate(item:CapabilitySkill){store.selectSkill(item.name);store.chatMode='auto';await router.push('/chat')}
async function inspect(name:string){const attempt=++detailAttempt;detail.value=null;detailError.value='';detailLoading.value=true;dialog.value?.showModal();try{const value=await api.capabilitySkill(name);if(attempt===detailAttempt)detail.value=value}catch(e:any){if(attempt===detailAttempt)detailError.value=e.message}finally{if(attempt===detailAttempt)detailLoading.value=false}}
function closeDetail(){++detailAttempt;dialog.value?.close()}
onMounted(refresh)
watch(()=>route.query,()=>{tab.value=route.query.tab==='tools'?'tools':'skills';query.value=String(route.query.q||'')})
</script>
<template><section class="documents capability-page">
  <header class="capability-heading"><div><small>CAPABILITY LIBRARY</small><h1>能力中心</h1><p>选择本轮问答的能力，了解它可以使用的工具与范围。</p></div><div class="heading-actions"><button class="secondary" @click="store.paletteOpen=true">命令面板 <kbd>Ctrl K</kbd></button><RouterLink v-if="store.user?.role==='admin'" class="primary" to="/capabilities/manage"><ShieldCheck :size="16"/>管理 Skill / Tool</RouterLink></div></header>
  <div class="catalog-line"><span v-if="store.capabilityDirectory">目录修订 {{store.capabilityDirectory.revision}} · {{store.capabilityDirectory.skills.length}} 个 Skill · {{store.capabilityDirectory.tools.length}} 个 Tool</span><span v-else>能力目录</span><button class="ghost" :disabled="store.capabilityLoading" @click="refresh"><RefreshCw :size="14"/>刷新</button></div>
  <div class="catalog-controls"><div role="tablist" aria-label="能力类型"><button role="tab" :aria-selected="tab==='skills'" :class="{active:tab==='skills'}" @click="tab='skills'">Skill 能力</button><button role="tab" :aria-selected="tab==='tools'" :class="{active:tab==='tools'}" @click="tab='tools'">Tool 工具</button></div><label class="catalog-search"><Search :size="16"/><input v-model="query" aria-label="搜索能力" placeholder="名称、说明或工具分组"/></label><select v-model="filter" aria-label="按可用性筛选"><option value="all">全部状态</option><option value="available">可使用</option><option value="unavailable">不可使用</option></select></div>
  <p v-if="store.capabilityLoading" class="catalog-state" role="status">正在加载能力目录…</p><p v-else-if="store.capabilityError" class="catalog-state error" role="alert">{{store.capabilityError}}</p>
  <div v-else class="capability-grid"><article v-for="item in rows" :key="item.name" :class="{unavailable:!item.available}"><header><code>{{item.name}}</code><span :class="['availability',{available:item.available}]">{{availabilityLabel(item.availability_reason)}}</span></header><h2>{{item.description}}</h2><p class="card-meta">v{{item.version}} · {{roleLabel(item.required_roles)}}</p><template v-if="'tool_names' in item"><p class="tool-list">{{item.tool_names.length?item.tool_names.join(' · '):'仅提供指令，不额外开放工具'}}</p><footer><button class="ghost" :disabled="!item.available" @click="inspect(item.name)">查看说明</button><button class="primary" :disabled="!item.available" @click="activate(item as CapabilitySkill)">使用能力 <ArrowUpRight :size="15"/></button></footer></template><template v-else><dl><div><dt>网络范围</dt><dd>{{networkLabel(item.network_policy)}}</dd></div><div><dt>执行策略</dt><dd>{{item.requires_approval?'需要审批':item.idempotent?'允许安全重试':'不自动重复副作用'}}</dd></div></dl><p v-if="item.requires_approval" class="card-meta">审批链路将在后续阶段开放，当前不能执行。</p></template></article><p v-if="!rows.length" class="catalog-state">没有匹配的能力。</p></div>
  <dialog ref="dialog" class="skill-detail" aria-labelledby="skill-detail-title" @cancel="closeDetail"><header><h2 id="skill-detail-title">Skill 说明</h2><button class="icon" aria-label="关闭 Skill 说明" @click="closeDetail"><X/></button></header><p v-if="detailLoading" role="status">正在读取…</p><p v-if="detailError" role="alert" class="error">{{detailError}}</p><template v-if="detail"><code>{{detail.name}} · v{{detail.version}}</code><p>{{detail.description}}</p><pre>{{detail.instructions}}</pre><small>工具：{{detail.tool_names.join(' · ')||'无'}}</small></template></dialog>
</section></template>
<style scoped>
.capability-page{max-width:1300px}.capability-heading{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-bottom:28px}.capability-heading small{letter-spacing:.15em;color:var(--green);font-size:10px}.capability-heading h1{font-family:'Noto Serif SC',serif;font-size:36px;margin:12px 0}.capability-heading p{font-size:13px;color:var(--muted);line-height:1.8}.heading-actions{display:flex;gap:10px;flex-wrap:wrap}.heading-actions a{display:flex;gap:8px;align-items:center;text-decoration:none;font-size:12px}.catalog-line{display:flex;justify-content:space-between;align-items:center;border-block:1px solid var(--line);padding:14px 0;font-size:11px;color:var(--muted)}.catalog-controls{display:flex;align-items:center;gap:16px;flex-wrap:wrap;margin:22px 0}.catalog-controls [role=tablist]{display:flex;gap:6px}.catalog-controls [role=tab]{padding:9px 14px;border:1px solid var(--line);border-radius:6px;background:transparent;color:var(--muted)}.catalog-controls [role=tab].active{background:var(--green);border-color:var(--green);color:white}.catalog-search{display:flex;gap:8px;align-items:center;flex:1;min-width:190px;padding:9px 12px;border:1px solid var(--line);border-radius:6px}.catalog-search input{width:100%;border:0;outline:0;background:transparent;color:var(--ink);font:inherit;font-size:12px}select{padding:10px;border:1px solid var(--line);border-radius:6px;background:var(--surface);color:var(--ink)}.capability-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.capability-grid article{display:flex;flex-direction:column;padding:24px;border:1px solid var(--line);border-radius:9px;background:var(--surface)}article header,article footer{display:flex;justify-content:space-between;align-items:center;gap:14px}.availability{font-size:10px;color:var(--muted);white-space:nowrap}.availability.available{color:var(--green)}code{font-size:11px;color:var(--green);overflow-wrap:anywhere}article h2{font-family:'Noto Serif SC',serif;font-size:21px;line-height:1.6;margin:22px 0 8px}.card-meta,.tool-list{font-size:11px;color:var(--muted);line-height:1.8;overflow-wrap:anywhere}.tool-list{padding-top:10px;margin-bottom:24px}article footer{margin-top:auto;border-top:1px solid var(--line);padding-top:16px}dl{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:22px}dt{font-size:10px;color:var(--muted)}dd{font-size:12px;margin:7px 0}button:disabled{opacity:.45;cursor:not-allowed}.catalog-state{padding:35px 0;color:var(--muted);font-size:13px}.error{color:var(--red)}.skill-detail{width:min(650px,92vw);max-height:80vh;overflow:auto;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-radius:12px;padding:28px}.skill-detail::backdrop{background:#102c2266}.skill-detail header{display:flex;justify-content:space-between;align-items:center}.skill-detail h2{font-family:'Noto Serif SC',serif;font-size:24px}.skill-detail pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;font-size:13px;line-height:1.9;padding:20px;background:var(--green2)}.skill-detail p,.skill-detail small{color:var(--muted);font-size:12px;line-height:1.8}@media(max-width:780px){.capability-heading{align-items:flex-start;flex-direction:column}.capability-grid{grid-template-columns:1fr}.capability-heading h1{font-size:29px}}
</style>
